import type {
  Vehicle,
  Category,
  Attribute,
  CreateVehicleData,
  UpdateVehicleData,
  Review,
} from '@/types/vehicle'
import type { User, UserSessionInfo } from '@/types/user'
import type { SignInRequest, SignUpRequest } from '@/types/api'
import type { Booking, CreateBookingRequest } from '@/types/booking'
import type { AddAttributesPayload } from '@/hooks/useAddAttributesToVehicle'
import type { CreateReviewRequest } from '@/types/review'

const api = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || 'http://localhost:1337/api',
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
})

api.interceptors.request.use(config => {
  const jwt = localStorage.getItem('jwt')
  if (jwt) {
    config.headers.Authorization = `Bearer ${jwt}`
  }
  return config
})

export const apiService = {
  signIn: async (requestData: SignInRequest): Promise<UserSessionInfo> => {
    const response = await api.post('/auth/local', requestData)
    return response.data
  },

  signUp: async (requestData: SignUpRequest): Promise<UserSessionInfo> => {
    const response = await api.post('/auth/local/register', requestData)
    return response.data
  },

  getCurrentUser: async (): Promise<User> => {
    const response = await api.get('/users/me?populate=*')
    return response.data
  },

  updateCurrentUser: async (userId: string, userData: Partial<User>): Promise<User> => {
    const response = await api.put(`/users/${userId}`, userData)
    return response.data
  },

  getUserStats: async (): Promise<{ totalTripsAsOwner: number; totalTripsAsRenter: number }> => {
    const [ownerRes, renterRes] = await Promise.all([
      api.get('/users/me/stats/owner'),
      api.get('/users/me/stats/renter'),
    ])

    return {
      totalTripsAsOwner: ownerRes.data.totalTripsAsOwner ?? 0,
      totalTripsAsRenter: renterRes.data.totalTripsAsRenter ?? 0,
    }
  },

  getAllVehicles: async (from?: string, to?: string, ownerId?: string): Promise<Vehicle[]> => {
    const queryParts: string[] = []

    if (from) queryParts.push(`available_from=${from}`)
    if (to) queryParts.push(`available_to=${to}`)
    if (!ownerId) queryParts.push('filters[current_status][$eq]=active')
    if (ownerId) queryParts.push(`filters[user_id][id][$eq]=${ownerId}`)

    queryParts.push('populate[user_id][populate][avatar]=true')
    queryParts.push('populate[images]=true')
    queryParts.push('populate[features]=true')
    queryParts.push('populate[attributes][populate][attribute_id]=true')
    queryParts.push('populate[attributes][populate][attribute_option_id]=true')
    queryParts.push('populate[category_id]=true')
    queryParts.push('populate[reviews]=true')
    queryParts.push('pagination[pageSize]=50')

    const response = await api.get(`/vehicles?${queryParts.join('&')}`)

    return response.data.data
  },
}

export const bookingService = {
  createBooking: async (bookingData: CreateBookingRequest): Promise<Booking> => {
    const response = await api.post('/bookings', bookingData)
    return response.data.data
  },

  getBookingById: async (documentId: string): Promise<Booking> => {
    const params: string[] = []

    params.push(
      'populate[vehicle][populate][images][populate]=*',
      'populate[vehicle][populate][category_id][populate]=*',
      'populate[vehicle][populate][user_id][fields][0]=firstname',
      'populate[vehicle][populate][user_id][fields][1]=lastname',
      'populate[vehicle][populate][user_id][fields][2]=email',
      'populate[vehicle][populate][user_id][fields][3]=phone',
      'populate[vehicle][populate][user_id][populate][avatar][populate]=*'
    )

    const query = params.length > 0 ? `?${params.join('&')}` : ''
    const response = await api.get(`/bookings/${documentId}${query}`)
    return response.data.data
  },

  getUserBookings: async (userId: number): Promise<Booking[]> => {
    const populateQuery = [
      // Usuario que reserva
      'populate[users_permissions_user]=true',
      'populate[vehicle][populate][user_id]=true',
      'populate[vehicle][populate][images]=true',

      // Poblamos las reseñas del vehículo (y el usuario que reseñó)
      'populate[vehicle][populate][reviews][populate]=users_permissions_user',
    ].join('&')

    const filterQuery = `filters[users_permissions_user][id][$eq]=${userId}`

    // Hacemos el GET directo al endpoint con la cadena de consulta segura
    const response = await api.get(`/bookings?${filterQuery}&${populateQuery}`)
    return response.data.data
  },
}

export const createVehicleService = {
  getVehicleById: async (id: string): Promise<Vehicle> => {
    const response = await api.get(`/vehicles/${id}`, {
      params: {
        populate: {
          category_id: true,
          user_id: {
            fields: ['username', 'email', 'firstname', 'lastname', 'createdAt', 'verified'],
          },
          attributes: {
            populate: ['attribute_id'],
          },
          features: true,
        },
      },
    })
    return response.data.data
  },

  // Need to check out this one and it´s fields in src/types/vehicle.ts
  createVehicle: async (vehicleData: CreateVehicleData): Promise<Vehicle> => {
    const response = await api.post('/vehicles', { data: vehicleData })
    return response.data.data
  },

  // Need to check out this one, too
  updateVehicle: async (id: string, vehicleData: UpdateVehicleData): Promise<Vehicle> => {
    const response = await api.put(`/vehicles/${id}`, { data: vehicleData })
    return response.data.data
  },

  deleteVehicle: async (id: string): Promise<void> => {
    await api.delete(`/vehicles/${id}`)
  },
}

export const reviewService = {
  createReview: async (reviewData: CreateReviewRequest): Promise<any> => {
    const response = await api.post('/reviews', { data: reviewData })
    return response.data.data
  },

  getUserReviews: async (userId: number): Promise<Review[]> => {
    const filterQuery = `filters[users_permissions_user][id][$eq]=${userId}`
    const populateQuery = 'populate[vehicle]=true' // Poblar el vehículo en cada reseña
    const response = await api.get(`/reviews?${filterQuery}&${populateQuery}`)
    return response.data.data
  },
}

export const vehicleService = {
  getVehicle: async (vehicleDocumentId: string): Promise<Vehicle> => {
    const populateQuery = [
      // Populate attributes and their nested relations
      'populate[attributes][populate][attribute_id][fields][0]=attribute',
      'populate[attributes][populate][attribute_option_id][fields][0]=value',

      // Populate user and their avatar
      'populate[user_id][populate][avatar]=true',
      'populate[user_id][fields][0]=firstname',
      'populate[user_id][fields][1]=lastname',
      'populate[user_id][fields][2]=username',
      'populate[user_id][fields][3]=confirmed',
      'populate[user_id][fields][4]=createdAt',

      // Populate reviews and their authors with avatars
      'populate[reviews][populate][users_permissions_user][fields][0]=firstname',
      'populate[reviews][populate][users_permissions_user][fields][1]=lastname',
      'populate[reviews][populate][users_permissions_user][fields][2]=username',
      'populate[reviews][populate][users_permissions_user][populate][avatar]=true',

      // Populate images
      'populate[images]=true',

      // Populate features
      'populate[features][fields][0]=name',

      // Populate category
      'populate[category_id][fields][0]=value',
    ].join('&')
    const response = await api.get(`/vehicles/${vehicleDocumentId}?${populateQuery}`)
    return response.data.data
  },

  getAllCategories: async (): Promise<Category[]> => {
    const queryParams = new URLSearchParams()
    queryParams.append('populate', '*')

    const response = await api.get(`/categories?${queryParams.toString()}`, {})
    return response.data.data
  },

  getAttributesByCategory: async (categoryId: number): Promise<Attribute[]> => {
    const queryParams = new URLSearchParams()
    queryParams.append('filters[category_id][id][$eq]', String(categoryId))
    queryParams.append('populate', '*')

    const response = await api.get(`/attributes?${queryParams.toString()}`)
    return response.data.data
  },

  getAllFeaturesByCategory: async (categoryId: number) => {
    const queryParams = new URLSearchParams()
    queryParams.append('filters[category_id][id][$eq]', String(categoryId))
    queryParams.append('populate', '*')

    const response = await api.get(`/features?${queryParams.toString()}`)
    return response.data.data
  },

  getOptionsByAttribute: async (attributeId: number) => {
    const queryParams = new URLSearchParams()
    queryParams.append('filters[attribute_id][id][$eq]', String(attributeId))
    queryParams.append('populate', '*')
    const response = await api.get(`/attribute-options?${queryParams.toString()}`)
    return response.data.data
  },

  getBookingsFromVehicle: async (vehicleDocumentId: string) => {
    const queryParams = new URLSearchParams()
    queryParams.append('filters[documentId][$eq]=', vehicleDocumentId)
    queryParams.append('populate[bookings][populate]', 'users_permissions_user')

    const response = await api.get(`/vehicles?${queryParams.toString()}`)

    const vehicleDataArray = response.data.data

    if (!vehicleDataArray || vehicleDataArray.length === 0) {
      return []
    }
    const vehicleItem = vehicleDataArray[0]

    const rawBookings = vehicleItem.bookings || []

    if (Array.isArray(rawBookings)) {
      return rawBookings.map((booking: any) => {
        const rawUser = booking.users_permissions_user

        const normalizedUser = {
          firstname: rawUser?.firstname || rawUser?.username || 'N/A',
          lastname: rawUser?.lastname || '',
        }

        return {
          ...booking,
          id: booking.id,
          user: normalizedUser,
        }
      })
    }

    return []
  },

  createVehicle: async (vehicleData: CreateVehicleData): Promise<Vehicle> => {
    const response = await api.post('/vehicles', { data: vehicleData })
    return response.data.data
  },

  updateVehicle: async (
    vehicleDocumentId: string,
    updateData: UpdateVehicleData
  ): Promise<Vehicle> => {
    const response = await api.put(`/vehicles/${vehicleDocumentId}`, { data: updateData })
    return response.data.data
  },

  addAttributesToVehicle: (payload: AddAttributesPayload) => {
    return api.post(`/vehicle-attributes`, { data: payload }).then(r => r.data)
  },

  addFeaturesToVehicle: (vehicleId: number | string, featureIds: (number | string)[]) =>
    api.post(`/vehicles/${vehicleId}`, { data: { features: featureIds } }).then(r => r.data),

  uploadImages: (formData: FormData): Promise<any> => {
    return api
      .post(`/upload`, formData, { headers: { 'Content-Type': 'multipart/form-data' } })
      .then(r => r.data)
  },

  getVehicleAvailability: async (vehicleId: string, from?: string, to?: string) => {
    const rangeDates: string[] = []
    if (from) rangeDates.push(`startDate=${from}`)
    if (to) rangeDates.push(`endDate=${to}`)
    const params = rangeDates.length > 0 ? `?${rangeDates.join('&')}` : ''
    const url = `/vehicles/${vehicleId}/availability${params}`
    const response = await api.get(url)
    return response.data
  },
}

