  getAllVehicles: async (from?: string, to?: string, ownerId?: string): Promise<Vehicle[]> => {
    const queryParts: string[] = []

    if (from) queryParts.push(`available_from=${from}`)
    if (to) queryParts.push(`available_to=${to}`)
    if (!ownerId) queryParts.push('filters[current_status][$eq]=active')
    if (ownerId) queryParts.push(`filters[user_id][id][$eq]=${ownerId}`)

    queryParts.push('populate[user_id][populate][avatar]=true')
    queryParts.push('populate[images]=true')
    queryParts.push('populate[features]=true')
    queryParts.push('populate[attributes][populate][attribute_id]=true')
    queryParts.push('populate[attributes][populate][attribute_option_id]=true')
    queryParts.push('populate[category_id]=true')
    queryParts.push('populate[reviews]=true')
    queryParts.push('pagination[pageSize]=50')

    const response = await api.get(`/vehicles?${queryParts.join('&')}`)

    return response.data.data
  },
}

